const incoming = $input.first().json.body ?? $input.first().json;
const resumeText = String(incoming.resumeText ?? '').trim();
const jobDescription = String(incoming.jobDescription ?? '').trim();

if (!resumeText || !jobDescription) {
  throw new Error('Both resumeText and jobDescription are required.');
}

const prompt = `You are an evidence-based resume screening assistant. Return ONLY one valid JSON object, with no markdown or extra text.

JOB DESCRIPTION:
${jobDescription.slice(0, 12000)}

RESUME TEXT:
${resumeText.slice(0, 12000)}

Extract the candidate's name and experience only from the resume. Never use the uploaded filename as a name. If the name is absent, use "Name not identified in resume". Report professional experience only when supported by the resume; do not count education or projects as employment years. If years are not stated, use null for experienceYears and "Not stated in resume" for experience. Use null for requiredExperienceYears unless the job description explicitly states a minimum.

Extract concise skills and specific qualifications required by the job description. matchedSkills must contain only requirements with direct evidence in the resume. missingSkills must contain the remaining required items that are not evidenced in the resume; absence from the resume does not prove the candidate lacks a skill. Use the same canonical labels in requiredSkills, matchedSkills, and missingSkills. relevantExperience is true only for relevant work or internship evidence stated in the resume. Write a realistic 2-4 sentence summary grounded in both texts, distinguishing documented evidence from gaps. Do not invent a score or hiring recommendation; the application calculates those.

Return exactly this JSON shape:
{"candidateName":"Name not identified in resume","experience":"Not stated in resume","experienceYears":null,"relevantExperience":false,"requiredExperienceYears":null,"requiredSkills":["Python"],"matchedSkills":["Python"],"missingSkills":[],"summary":"Evidence-based 2-4 sentence assessment."}`;

return [{ json: { prompt } }];

const response = $input.first().json;
const raw = response.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
const cleaned = String(raw).replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) throw new Error(`Gemini returned invalid JSON: ${cleaned.slice(0, 200)}`);
  result = JSON.parse(match[0]);
}

const required = ['candidateName', 'experience', 'experienceYears', 'relevantExperience', 'requiredExperienceYears', 'requiredSkills', 'matchedSkills', 'missingSkills', 'summary'];
for (const field of required) {
  if (!(field in result)) throw new Error(`Gemini response is missing ${field}.`);
}

return [{ json: result }];
